export class JSXNode implements HtmlEscaped {
  tag: string | Function
  props: Props
  key?: string
  children: Child[]
  isEscaped: true = true as const
  constructor(tag: string | Function, props: Props, children: Child[]) {
    if (typeof tag !== 'function' && !isValidTagName(tag)) {
      throw new Error(`Invalid JSX tag name: ${tag}`)
    }
    this.tag = tag; this.props = props; this.children = children
  }

class JSXFunctionNode extends JSXNode {
  override toStringToBuffer(buffer): void {
    const props = { ...this.props }
    if (this.children.length) {
      props.children = this.children.length === 1 ? this.children[0] : this.children
    }
    const res = (this.tag as Function).call(null, props)
    if (typeof res === 'boolean' || res == null) { return }
    else if (res instanceof Promise) {
      const ctx = globalContexts.length ? captureRenderContext() : undefined
      buffer.unshift('', resolveFunctionComponentResult(res, ctx))
    } else if (res instanceof JSXNode) { res.toStringToBuffer(buffer) }
    else if (Array.isArray(res)) { childrenToStringToBuffer(res, buffer) }
  }
}

export const jsx = (tag: string | Function, props: Props | null, ...children: Child[]): JSXNode => {
  props ??= {}
  if (children.length) {
    props.children = children.length === 1 ? children[0] : children
  }
  const key = props.key
  delete props['key']
  const node = jsxFn(tag, props, children)
  node.key = key
  return node
}

const childrenToStringToBuffer = (children: Child[], buffer): void => {
  for (let i = 0, len = children.length; i < len; i++) {
    const child = children[i]
    if (typeof child === 'string') { escapeToBuffer(child, buffer) }
    else if (typeof child === 'boolean' || child === null || child === undefined) { continue }
    else if (child instanceof JSXNode) { child.toStringToBuffer(buffer) }
    else if (typeof child === 'number') { (buffer[0] as string) += child }
    else if ((child as unknown as HtmlEscaped).isEscaped) { (buffer[0] as string) += child }
    else if (child instanceof Promise) { buffer.unshift('', child) }
    else if (Array.isArray(child)) { childrenToStringToBuffer(child, buffer) }
  }
}

