export const Suspense = async ({ children, fallback }) => {
  try {
    buildDataStack.push([[], stackNode])
    resArray = children.map(serializeBoundaryChild)
  } catch (e) {
    if (e instanceof Promise) {
      const resume = captureRenderContext()
      resArray = [e.then(() => resume(() => childrenToString(children)))]
    } else { throw e }
  } finally { popNodeStack() }
  if (resArray.some((r) => r instanceof Promise)) {
    return raw(`<template id="H:N"></template>${fallbackStr}<!--/$-->`, [streamCb])
  }
  return raw(resArray.join(''))
}

export const createContextProviderFunction =
  <T>(values: T[]): Function =>
  ({ value, children }) => {
    const props = { children: [
      { tag: setInternalTagFlag(() => values.push(value)), props: {} },
    ] }
    if (Array.isArray(children)) props.children.push(...children.flat())
    else props.children.push(children)
    props.children.push({ tag: setInternalTagFlag(() => values.pop()), props: {} })
    const res = { tag: '', props }
    res[DOM_ERROR_HANDLER] = (err) => { values.pop(); throw err }
    return res
  }
